'use client';
import { useEffect, useRef, useState, type CSSProperties } from 'react';
import { cssEase, useStudioMotion } from '../../motion';
import type { EffectProps } from '../../types';
import styles from './styles.module.css';

type Params = { axis: 'y' | 'x'; duration: number; perspective: number; lift: number };

const INCLUDED = [
  ['Recipes', 'Every motion and 3D recipe'],
  ['Seats', 'Five editors, unlimited viewers'],
  ['Reviews', 'Two motion reviews a month'],
  ['Support', 'Reply within two working days'],
  ['Licence', 'One product, perpetual'],
] as const;

export default function FlipCard3d({ params }: EffectProps<Params>) {
  const { reduced, scale } = useStudioMotion();
  /** Half-turn counter: the card keeps turning the same way rather than unwinding. */
  const [turns, setTurns] = useState(0);
  const flipped = turns % 2 === 1;
  const lift = useRef<HTMLDivElement>(null);
  const shadow = useRef<HTMLDivElement>(null);
  const lights = useRef<(HTMLSpanElement | null)[]>([]);
  const buttons = useRef<(HTMLButtonElement | null)[]>([]);
  const running = useRef<Animation[]>([]);
  const first = useRef(true);
  const ms = Math.round(params.duration * scale.duration);

  useEffect(() => {
    if (first.current) { first.current = false; return; }
    // The side that was focused just became inert: hand focus to the visible side.
    buttons.current[flipped ? 1 : 0]?.focus({ preventScroll: true });
    running.current.forEach((a) => a.cancel());
    running.current = [];
    if (reduced || typeof Element.prototype.animate !== 'function') return;
    const timing: KeyframeAnimationOptions = { duration: ms, easing: cssEase('inOut') };
    const add = (el: Element | null | undefined, frames: Keyframe[]) => { if (el) running.current.push(el.animate(frames, timing)); };
    add(lift.current, [{ transform: 'translateZ(0)' }, { transform: `translateZ(${params.lift}px)` }, { transform: 'translateZ(0)' }]);
    add(shadow.current, [
      { transform: 'scale(1)', opacity: 0.55 },
      { transform: `scale(${params.axis === 'y' ? '0.72, 1.04' : '1.04, 0.6'})`, opacity: 0.28 },
      { transform: 'scale(1)', opacity: 0.55 },
    ]);
    for (const el of lights.current) add(el, [{ opacity: 0, backgroundPosition: '0% 0%' }, { opacity: 1, offset: 0.5 }, { opacity: 0, backgroundPosition: '100% 100%' }]);
  }, [turns]); // eslint-disable-line react-hooks/exhaustive-deps -- params are read at flip time on purpose
  useEffect(() => () => running.current.forEach((a) => a.cancel()), []);

  const rotate = params.axis === 'x' ? 'rotateX' : 'rotateY';
  const flip = () => setTurns((t) => t + 1);

  return (
    <div
      className={styles.root}
      data-reduced={reduced || undefined}
      data-axis={params.axis}
      style={{ '--persp': `${params.perspective}px`, '--dur': `${ms}ms` } as CSSProperties}
    >
      <div className={styles.shadow} ref={shadow} aria-hidden="true" />
      <div className={styles.lift} ref={lift}>
        <div className={styles.card} style={reduced ? undefined : { transform: `${rotate}(${turns * 180}deg)` }}>
          <section className={`${styles.face} ${styles.front}`} aria-label="Studio plan summary" inert={flipped} data-shown={!flipped || undefined}>
            <p className={styles.kicker}><span>Studio plan</span><span>Sample pricing</span></p>
            <p className={styles.price}><span className={styles.amount}>€480</span><span className={styles.per}>per month, billed yearly</span></p>
            <p className={styles.lede}>For a product team shipping motion every sprint.</p>
            <ul className={styles.points}>
              <li>All recipes, 3D included</li>
              <li>Five editor seats</li>
              <li>Two motion reviews a month</li>
            </ul>
            <button type="button" className={styles.action} ref={(el) => { buttons.current[0] = el; }} onClick={flip}>
              See what’s included <Turn />
            </button>
            <span className={styles.light} ref={(el) => { lights.current[0] = el; }} aria-hidden="true" />
          </section>

          <section className={`${styles.face} ${styles.back}`} aria-label="Studio plan details" inert={!flipped} data-shown={flipped || undefined}>
            <p className={styles.kicker}><span>What’s included</span><span>Sample data</span></p>
            <dl className={styles.table}>
              {INCLUDED.map(([k, v]) => (
                <div key={k}><dt>{k}</dt><dd>{v}</dd></div>
              ))}
            </dl>
            <p className={styles.note}>Cancel any time; the recipes you have shipped stay licensed.</p>
            <button type="button" className={styles.action} ref={(el) => { buttons.current[1] = el; }} onClick={flip}>
              Back to summary <Turn />
            </button>
            <span className={styles.light} ref={(el) => { lights.current[1] = el; }} aria-hidden="true" />
          </section>
        </div>
      </div>
    </div>
  );
}

function Turn() {
  return (
    <svg viewBox="0 0 16 16" width="16" height="16" aria-hidden="true">
      <path d="M3 8a5 5 0 0 1 8.6-3.5L13 6M13 3v3h-3M13 8a5 5 0 0 1-8.6 3.5L3 10M3 13v-3h3" fill="none" stroke="currentColor" strokeWidth="1.4" strokeLinecap="round" strokeLinejoin="round" />
    </svg>
  );
}

.root {
  position: relative;
  width: min(100% - 32px, 380px);
  margin: 36px 0 44px;
  perspective: var(--persp, 1200px);
  font-family: var(--s3-font-text, ui-sans-serif, system-ui, sans-serif);
}
.shadow {
  position: absolute;
  inset: auto 6% -22px;
  height: 36px;
  border-radius: 50%;
  background: radial-gradient(closest-side, #0b0b0966, #0b0b0900);
  filter: blur(6px);
  opacity: 0.55;
}
.lift { transform-style: preserve-3d; }
.card {
  display: grid;
  transform-style: preserve-3d;
  transition: transform var(--dur, 640ms) var(--s3-ease-inOut, cubic-bezier(0.65, 0, 0.35, 1));
}
.face {
  position: relative;
  grid-area: 1 / 1;
  display: flex;
  flex-direction: column;
  gap: 14px;
  padding: clamp(18px, 6cqi, 28px);
  border-radius: var(--s3-radius-l, 18px);
  border: 1px solid var(--s3-line, #11110f24);
  backface-visibility: hidden;
  overflow: hidden;
}
.front { background: #f3f0e8; color: #11110f; --soft: #11110fa6; --rule: #11110f24; }
.back { background: #171714; color: #f3f0e8; --soft: #f3f0e8b3; --rule: #f3f0e82e; }
.root[data-axis='y'] .back { transform: rotateY(180deg); }
.root[data-axis='x'] .back { transform: rotateX(180deg); }
.kicker {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  margin: 0;
  font-family: var(--s3-font-mono, ui-monospace, monospace);
  font-size: 0.6875rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--soft);
}
.price { display: grid; gap: 2px; margin: 18px 0 0; }
.amount {
  font-family: var(--s3-font-display, ui-sans-serif, system-ui, sans-serif);
  font-size: clamp(3rem, 20cqi, 4.75rem);
  font-weight: 700;
  line-height: 0.9;
  letter-spacing: -0.05em;
}
.per { font-size: 0.8125rem; color: var(--soft); }
.lede { margin: 0; font-size: 1rem; line-height: 1.35; max-width: 26ch; }
.points { display: grid; gap: 6px; margin: 0; padding: 0; list-style: none; font-size: 0.875rem; color: var(--soft); }
.points li { display: flex; gap: 10px; align-items: baseline; }
.points li::before { content: ''; flex: none; width: 6px; height: 6px; border-radius: 50%; background: #e03a0c; transform: translateY(-1px); }
.table { display: grid; margin: 6px 0 0; }
.table div { display: grid; grid-template-columns: 5.5rem 1fr; gap: 12px; padding: 10px 0; border-top: 1px solid var(--rule); font-size: 0.875rem; line-height: 1.35; }
.table dt { font-family: var(--s3-font-mono, ui-monospace, monospace); font-size: 0.6875rem; letter-spacing: 0.08em; text-transform: uppercase; color: var(--soft); padding-top: 2px; }
.table dd { margin: 0; }
.note { margin: 0; padding-top: 10px; border-top: 1px solid var(--rule); font-size: 0.8125rem; line-height: 1.4; color: var(--soft); }
.action {
  display: inline-flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  min-height: 44px;
  margin-top: auto;
  padding: 0 16px;
  border: 1px solid currentColor;
  border-radius: 999px;
  background: transparent;
  color: inherit;
  font: inherit;
  font-size: 0.9375rem;
  font-weight: 500;
  cursor: pointer;
  transition: background-color var(--s3-duration-fast, 160ms), color var(--s3-duration-fast, 160ms);
}
.front .action:hover { background: #11110f; color: #f3f0e8; }
.back .action:hover { background: #f3f0e8; color: #11110f; }
.action:focus-visible { outline: 2px solid currentColor; outline-offset: 3px; }
/* A band of light that crosses the face mid-turn. */
.light {
  position: absolute;
  inset: 0;
  background: linear-gradient(115deg, #ffffff00 30%, #ffffff59 48%, #ffffff00 62%) 0% 0% / 300% 300% no-repeat, linear-gradient(#0b0b0933, #0b0b0933);
  opacity: 0;
  pointer-events: none;
}

/* Reduced motion: flat cross-fade, no 3D. */
.root[data-reduced] .card { transition: none; transform: none; }
.root[data-reduced] .face { transform: none; backface-visibility: visible; opacity: 0; visibility: hidden; transition: opacity 160ms linear, visibility 0s linear 160ms; }
.root[data-reduced] .face[data-shown] { opacity: 1; visibility: visible; transition: opacity 160ms linear; }
@media (prefers-reduced-motion: reduce) {
  .card, .action { transition: none; }
}
